from collections import Counter
from datetime import date,timedelta
from decimal import Decimal,ROUND_HALF_UP
import json,re
from pathlib import Path
from travel_expense_claim.verify_independence import Sources
from jsonschema import Draft202012Validator,FormatChecker

root=Path.cwd(); out=Path('/private/tmp/travel-expense-skill-forward-qu098708')
s=Sources(root/'artifacts/runs/submission-20261017T154939Z/sources.json')
r=json.loads((out/'unsealed-preview-result.json').read_text())

def f(t,label):
    m=re.search(r'^\s*'+re.escape(label)+r':\s*([^\n]+)',t,re.M)
    return m.group(1).strip() if m else None

def money(v): return int((Decimal(str(v))*100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))

receipts={}
for page in s.read('RECEIPTS-PAGES'):
    for block in re.split(r'(?=Receipt reference:)',page['text'])[1:]:
        receipts[f(block,'Receipt reference')]={key:f(block,key) for key in ('Expense reference','Employee','Trip reference','Category','Currency','Gross amount','Documented units','Issued date')}
versions=[]
for sid in ('INITIAL-PAGES','UPDATES-PAGES'):
    for page in s.read(sid):
        text=page['text']
        lines=re.findall(r'^\s*\d+\s+(\S+)\s+(\S+)\s+(\d{4}-\d{2}-\d{2})\s+(\d+\.\d+)\s+([A-Z]{3})\s*$',text,re.M)
        assert lines
        versions.append(dict(id=f(text,'Claim reference'),revision=int(f(text,'Revision')),batch=int(f(text,'Arrival batch')),employee=f(text,'Employee'),trip=f(text,'Trip reference'),lines=lines,exception_cost=f(text,'Expense reference'),replacement=f(text,'Allowed original amount')))
trips={row['Trip reference']:row for row in s.table('Trips')}
merchant=s.table('Merchant payments'); caps=s.table('Caps'); fx=s.table('FX'); native=s.table('Finance activity')
errors=[]; checked_lines=0
for snapshot in r['snapshots']:
    batch=int(snapshot['batch_id']); selected={}
    for v in versions:
        if v['batch']<=batch and (v['id'] not in selected or v['revision']>selected[v['id']]['revision']): selected[v['id']]=v
    assert set(selected)=={c['claim_id'] for c in snapshot['claims']}
    for claim in snapshot['claims']:
        original=selected[claim['claim_id']]
        for cost,receipt_id,first_filed,gross,currency in original['lines']:
            rec=receipts[receipt_id]; gross=Decimal(gross)
            expected=(cost,original['employee'],original['trip'],currency,gross,receipt_id)
            payments=[p for p in merchant if tuple(p[k] for k in ('Expense reference','Employee ID','Trip reference','Currency','Gross amount','Receipt reference'))==expected and p['Payment status']=='settled' and p['Paid date']<=s.data['case_clock']]
            rec_identity=(rec['Expense reference'],rec['Employee'],rec['Trip reference'],rec['Currency'],Decimal(rec['Gross amount']),receipt_id)
            amount=None
            if rec_identity==expected and len(payments)==1:
                category=rec['Category']; paid=payments[0]['Paid date']; value=None
                if category in {'transport','conference'}: value=gross
                elif category=='personal': value=Decimal(0)
                elif category in {'lodging','meals'}:
                    applicable=[]
                    for c in caps:
                        start=(date(1899,12,30)+timedelta(days=int(c['Effective from']))).isoformat(); end=(date(1899,12,30)+timedelta(days=int(c['Effective to']))).isoformat()
                        if (c['Destination'],c['Category'],c['Currency'])==(trips[original['trip']]['Destination'],category,currency) and start<=paid<=end: applicable.append(c)
                    units=Decimal(rec['Documented units'])
                    if len(applicable)==1 and units>0 and units==units.to_integral_value(): value=min(gross,Decimal(str(applicable[0]['Amount per unit']))*units)
                if value is not None:
                    if original['replacement'] is not None and original['exception_cost']==cost: value=Decimal(original['replacement'])
                    rates=[Decimal(str(row['EUR per currency unit'])) for row in fx if row['Currency']==currency and row['Rate date']==paid]
                    rate=Decimal(1) if currency=='EUR' else rates[0] if len(rates)==1 else None
                    if rate is not None: amount=money(value*rate)
            observed=next(row for row in claim['lines'] if row['cost_id']==cost)['reviewed_cents']
            if amount != observed: errors.append((batch,claim['claim_id'],cost,amount,observed))
            checked_lines+=1
    visible=[e for e in native if e['Arrival batch']<=batch]; unique={}
    for event in visible:
        key=event['Activity reference']; payload={k:v for k,v in event.items() if k not in {'_ref','Arrival batch'}}
        assert key not in unique or unique[key]==payload
        unique[key]=payload
    gross_paid=sum(money(e['Amount (EUR)']) for e in unique.values() if e['Activity type']=='settled')
    refunds=sum(money(e['Amount (EUR)']) for e in unique.values() if e['Activity type']=='refund')
    summary=r['summaries'][batch-1]
    assert (summary['gross_paid_cents'],summary['refunded_cents'],summary['net_paid_cents'])==(gross_paid,refunds,gross_paid-refunds)
    assert set(snapshot['admitted_event_ids'])==set(unique)
    assert all(d['Arrival batch']<=batch for d in snapshot['decisions'])
    assert {d['Decision reference'] for d in snapshot['decisions']}=={p['Decision reference'] for p in snapshot['review_packets']}
    assert len(snapshot['admitted_event_ids'])==len(set(snapshot['admitted_event_ids']))
    for process in snapshot['travel_cancellations']:
        assert not set(process['admitted_cancellation_event_ids'])&set(snapshot['admitted_event_ids'])
    validator=Draft202012Validator(json.loads((root/'snapshot.schema.json').read_text()),format_checker=FormatChecker())
    assert not list(validator.iter_errors(snapshot))
assert not errors,errors
proof=dict(offline=True,independent_policy_line_calculations_checked=checked_lines,monetary_mismatches=errors,independent_receipt_records=len(receipts),raw_claim_versions=len(versions),raw_finance_delivery_types=dict(Counter(e['Activity type'] for e in native)),all_batches_schema_valid=True,visible_finance_ids_and_net_money_match_raw_rows=True,decisions_and_packets_arrival_bounded=True,cancellation_and_finance_ids_disjoint=True)
(out/'independent-source-crosschecks.json').write_text(json.dumps(proof,indent=2)+'\n')
print(json.dumps(proof,indent=2))
